118	    (session as { method?: unknown }).method !== "client" ||
119	    typeof (session as { slug?: unknown }).slug !== "string" ||
120	    typeof (session as { issuedAt?: unknown }).issuedAt !== "number"
121	  ) {
122	    return null;
123	  }
124	  const { slug, issuedAt, email, slugs } = session as {
125	    slug: string;
126	    issuedAt: number;
127	    email?: unknown;
128	    slugs?: unknown;
129	  };
130	  if (!SLUG_RE.test(slug)) return null;
131	  if (Date.now() - issuedAt >= MAX_AGE_MS) return null;
132	
133	  // A malformed email is dropped rather than failing the session: it carries no
134	  // authority, so losing it costs an attribution label, not access.
135	  const clean =
136	    typeof email === "string" && email.length > 0 && email.length <= MAX_EMAIL_LEN
137	      ? email.toLowerCase()
138	      : undefined;
139	
140	  // A malformed `slugs` array is dropped the same way: the session still
141	  // verifies as its single `slug`, just without the wider grant.
142	  const cleanSlugs =
143	    Array.isArray(slugs) && slugs.every((s) => typeof s === "string" && SLUG_RE.test(s)) && slugs.includes(slug)
144	      ? (slugs as string[])
145	      : undefined;
146	
147	  const result: ClientSession = { slug };
148	  if (clean) result.email = clean;
149	  if (cleanSlugs) result.slugs = cleanSlugs;
150	  return result;
151	}
