  // it. Decoding token-by-token means a malformed token just stays literal
  // instead of aborting the whole decode.
  const lenientDecodeOnce = (s: string) =>
    s.replace(/%[0-9A-Fa-f]{2}/g, (tok) => {
      try {
        return decodeURIComponent(tok);
      } catch {
        return tok;
      }
    });
  let dec = raw;
  for (let i = 0; i < 5; i++) {
    const d = lenientDecodeOnce(dec);
    if (d === dec) break;
    dec = d;
  }
  // Also fold backslashes to "/" (an encoded %5C decodes to "\", which some
  // static resolvers treat as a separator) and collapse "." / ".." segments, so a
  // traversal or separator-variant the resolver would normalise INTO a gated file
  // (e.g. /api/client/..%2f..%2fclient-docs%2fnomadik%2freference.html)
  // can't dodge the prefix test or slip through the /api allowlist. We then gate
  // on the raw, the token-decoded, and this normalised form - the union covers
  // every path that resolves under a gated namespace.
  const collapse = (path: string): string => {
    const out: string[] = [];
    for (const seg of path.split("/")) {
      if (seg === "..") out.pop();
      else if (seg !== "." && seg !== "") out.push(seg);
    }
    return "/" + out.join("/");
  };
  const p = collapse(dec.replace(/\\/g, "/")).toLowerCase();
  const rawLower = raw.toLowerCase();

  const underNomadik =
    p === "/nomadik" ||
    p.startsWith("/nomadik/") ||
    rawLower === "/nomadik" ||
    rawLower.startsWith("/nomadik/");
  const underHandymancf =
    p === "/handymanclonakilty" ||
    p.startsWith("/handymanclonakilty/") ||
    rawLower === "/handymanclonakilty" ||
    rawLower.startsWith("/handymanclonakilty/");
  const underClient =
    p === "/client" ||
    p.startsWith("/client/") ||
    rawLower === "/client" ||
    rawLower.startsWith("/client/");
  // Owner-only admin surface. Nested under /client so it must be tested BEFORE
  // the tenant gate - a tenant session must never open it, and its own cookie
  // (method 'owner') never opens a tenant's pages.
  const underAdmin =
    p === "/client/admin" ||
    p.startsWith("/client/admin/") ||
    rawLower === "/client/admin" ||
    rawLower.startsWith("/client/admin/");
  const underPartners =
    p === "/partners" ||
    p.startsWith("/partners/") ||
    rawLower === "/partners" ||
    rawLower.startsWith("/partners/");
  const underLab =
    p === "/lab" ||
    p.startsWith("/lab/") ||
    rawLower === "/lab" ||
    rawLower.startsWith("/lab/");
  // /internal - owner-only personal tooling pages (currently just the
  // email-ingest automation's hosted summaries). Same owner cookie as /lab.
  const underInternal =
    p === "/internal" ||
    p.startsWith("/internal/") ||
    rawLower === "/internal" ||
    rawLower.startsWith("/internal/");
