    // reassessment). `new NextResponse(null, { status: 404 })` sent a zero-byte
    // 404, so a visitor following a stale link to /services/consulting got the
    // browser's own error page: no header, no footer, no way back into the
    // site, and nothing saying whose site she had reached. Rewriting to a path
    // that cannot exist makes Next render app/not-found.tsx, which is branded
    // and links home, while the status stays 404 so crawlers read it the same
    // way as before.
    return NextResponse.rewrite(new URL("/_offline", req.url), { status: 404 });
  }

  // --- Gate 4: site-wide pre-launch ---
  const password = process.env.SITE_GATE_PASSWORD;
  if (!password) return NextResponse.next(); // gate off

  const user = process.env.SITE_GATE_USER || "solaisoft";
  const header = req.headers.get("authorization") || "";

  if (header.startsWith("Basic ")) {
    try {
      const decoded = atob(header.slice(6));
      const sep = decoded.indexOf(":");
      const u = decoded.slice(0, sep);
      const pw = decoded.slice(sep + 1);
      if (u === user && pw === password) return NextResponse.next();
    } catch {
      // fall through to challenge
    }
  }

  return new NextResponse("Authentication required.", {
    status: 401,
    headers: {
      "WWW-Authenticate": 'Basic realm="Solaisoft preview", charset="UTF-8"',
      "Cache-Control": "no-store",
    },
  });
